        if _storage._completedAt != rhs_storage._completedAt {return false}
        if _storage._result != rhs_storage._result {return false}
        if _storage._verificationCodes != rhs_storage._verificationCodes {return false}
        if _storage._errorCode != rhs_storage._errorCode {return false}
        if _storage._errorMessage != rhs_storage._errorMessage {return false}
        if _storage._auditRef != rhs_storage._auditRef {return false}
        return true
      }
      if !storagesAreEqual {return false}
    }
    if lhs.unknownFields != rhs.unknownFields {return false}
    return true
  }
}
